Strategy.Code:
using System;
using System.IO;
using System.Windows.Forms;
using System.Collections.Generic;
using System.Text;
using System.Drawing;
using WealthLab;
using Community.Components;

namespace WealthLab.Strategies
{    
	public class BadHistoryDataCheck : WealthScript
	{        
		StrategyParameter _fullDataSet;			// if == 1, check entire DataSet 
		StrategyParameter _showOnlyErrors;		// if == 1, show only symbols with errors
		StrategyParameter _check4pmBar;			// if == 1, if last intraday bar is not 4pm, flag an error

		private Bars _bars = null;

		public BadHistoryDataCheck()
		{
			_fullDataSet = CreateParameter("Full DataSet", 0, 0, 1, 1);
			_showOnlyErrors = CreateParameter("Show Only Errors", 0, 0, 1, 1);
			_check4pmBar = CreateParameter("Check 4pm", 0, 0, 1, 1);
		}

		public int TradingDaysBetweenDates(DateTime dt1, DateTime dt2)
		{        
			int days = 0;
			dt1 = dt1.AddDays(1);
			while (dt1 < dt2)
			{                                    
				if (dt1.DayOfWeek != DayOfWeek.Saturday 
					&& dt1.DayOfWeek != DayOfWeek.Sunday
					&& !Bars.MarketInfo.Holidays.Contains(dt1) )
					days++;
				dt1 = dt1.AddDays(1);
			}
			return days;
		}

		protected override void Execute()
		{        
			ClearDebug();	
			_bars = Bars;
			Utility u = new Utility(this);			// Community.Components
			string dsName = u.GetDataSetName();	

			IList<string> badSymbols = new List<string>();

			bool intraday = Bars.BarInterval > 0;
			if (!intraday & !(Bars.Scale == BarScale.Daily))
			{
				string lbl = "Cannot perform Data Check in scale: " + Bars.Scale.ToString();
				PrintDebug(lbl);
				DrawLabel(PricePane, lbl, Color.Red);
				return;
			}

			DateTime Sept172001 = new DateTime(2001,9,17);  // First trading day after 9/11
			TimeSpan ts1300 = new TimeSpan(13,0,0);    		// 13:00:00 close for short days

			foreach (string sym in DataSetSymbols)
			{          				
				if (_fullDataSet.ValueInt != 1)
				{					
					if (sym != Bars.Symbol) continue;
				}
				else
				{
					FlushDebug();
					ClearExternalSymbols();
					try {
						_bars = GetExternalSymbol(dsName, sym, false);
						PrintStatusBar("Processing: " + sym);
					}
					catch(Exception e) {
						PrintDebug(e.Message);
						PrintDebug("-----");
						continue;
					}
				}

				if (_bars.Count == 0)
				{           
					PrintDebug("No data: " + _bars.Symbol);
					PrintDebug("-----");
					if (_fullDataSet.ValueInt != 1) return; else continue;
				}

				int badBars = 0;
				for(int bar = 2; bar < _bars.Count; bar++)
				{    
//					PrintDebug(bar);
					DateTime dt = _bars.Date[bar];
					DateTime dt1 = _bars.Date[bar - 1];
					// Check intraday last bar at 4pm
					if (intraday 
						&& _check4pmBar.ValueInt == 1 
						&& _bars.IntradayBarNumber(bar) == 0)
					{                            
						if (u.GetTime(_bars, bar-1) != 1600 && dt1.TimeOfDay != ts1300)
						{
							badBars++;
							PrintDebug(bar + " Last bar-of-day time: " + dt1.ToShortDateString() + " " + dt1.TimeOfDay);
						}
					}

					//Check for bars on Saturday or Sunday
					if (dt.DayOfWeek == DayOfWeek.Saturday || dt.DayOfWeek == DayOfWeek.Sunday)
					{
						badBars++;
						PrintDebug("Weekend bar: " + dt + " bar " + bar);
					}

					//Check for duplicate dates
					if (dt == dt1)
					{
						badBars++;
						PrintDebug("Duplicate date: " + dt + " bar " + bar);
					}

					//Check for zero close
					if (_bars.Close[bar] < 1e-7)
					{
						badBars++;
						PrintDebug("Zero Close: " + dt + " bar " + bar);	
					}

					//Check for open or close outside high/low range
					if (_bars.Open[bar] < _bars.Low[bar])
					{
						badBars++;
						PrintDebug("Open < Low: " + dt + " bar " + bar);
					}
					if (_bars.Open[bar] > _bars.High[bar])
					{
						badBars++;
						PrintDebug("Open > High: " + dt + " bar " + bar);
					}
					if (_bars.Close[bar] < _bars.Low[bar])
					{
						badBars++;
						PrintDebug("Close < Low: " + dt + " bar " + bar);
					}
					if (_bars.Close[bar] > _bars.High[bar])
					{
						badBars++;
						PrintDebug("Close > High: " + dt + " bar " + bar);
					}

					//Out of sequence dates
					if (dt < dt1)
					{
						PrintDebug("Out of sequence date at bar " + bar);
						PrintDebug(String.Format( "{0:yyyyMMdd HHmm }", _bars.Date[bar-2]));
						PrintDebug(String.Format( "{0:yyyyMMdd HHmm }", dt1));
						PrintDebug(String.Format( "{0:yyyyMMdd HHmm }", dt));
						PrintDebug("");
						badBars++;
					}

					//    Check for day gaps that are not weekends or holidays
					if (dt.Date != dt1.Date)
					{
						if (dt.Date == Sept172001) continue;
						TimeSpan ts = dt.Date - dt1.Date;
						if ( ts.Days > 1 )
						{
							int days = TradingDaysBetweenDates(dt1.Date, dt.Date);
							if (days > 1)
							{
								PrintDebug("Gap of " + days + " days in data at bar " + bar + " (" + dt.Date + ")");
								badBars++;
							}
						}
					}        
				}

				string msg = _bars.Symbol + "\t" + _bars.Scale.ToString();
				msg += "; Bars.Count = " + _bars.Count + "; " + _bars.Date[_bars.Count - 1].ToShortDateString();
				if (intraday)
					msg += " " + _bars.Date[_bars.Count - 1].ToShortTimeString();    

				string msg2 = _bars.Symbol;
				if (badBars == 0)
					msg2 += " OK!";
				else
				{
					msg2 += " bad bars: " + badBars;
					badSymbols.Add(_bars.Symbol);
				}                

				if ( badBars > 0 ||    (_showOnlyErrors.ValueInt == 0 && badBars == 0))
				{    
					PrintDebug(msg);
					PrintDebug(msg2);
					PrintDebug("-----");
					FlushDebug();
				}
			}    

			if (badSymbols.Count > 0)
			{
				DataSource ds = u.GetDataSource();

				if (ds.Provider.CanDeleteSymbolDataFile)
				{				
					DialogResult dr = MessageBox.Show(String.Format("Delete {0} data files with bad bars from the DataStore?", badSymbols.Count),
						String.Format("Warning! Delete {0} data files?", ds.ProviderName), 
						MessageBoxButtons.YesNoCancel, MessageBoxIcon.Exclamation, MessageBoxDefaultButton.Button2);
					if (dr.Equals(DialogResult.Yes))
					{													
						foreach (string sym in badSymbols)
						{		
							string fp = ds.Provider.DataStore.FileNameForSymbol(sym, Bars.Scale, Bars.BarInterval);
							if (System.IO.File.Exists(fp))
							{
								try 
								{
									ds.Provider.DeleteSymbolDataFile(ds, sym);
									PrintDebug("Deleted: " + fp);
									FlushDebug();
								}
								catch (Exception e) 
								{
									PrintDebug(e.Message);
								}	
							}
							else
							{
								PrintDebug("File not found: " + fp);
							}
						}
					}
				}
				else
				{
					MessageBox.Show(String.Format("{0} data files with bad bars.  See Debug Window for more info.", badSymbols.Count), 
						"Data Check Complete for " + ds.ProviderName, MessageBoxButtons.OK, MessageBoxIcon.Information);
				}
			}
			PrintStatusBar("Data Check Complete");

		}        
	}
}
